    auto savedProject=project;auto savedFile=currentFile;auto savedUndo=undoStack,savedRedo=redoStack;auto savedSelection=selectedNotes;int savedTrack=selectedTrack,savedNote=selectedNote,savedLow=pianoLow;double savedStart=pianoStart,savedSpan=pianoSpan;auto savedOptions=noteToolOptions;bool savedDirty=dirty;
    releaseKeys();cancelNoteTool();closeCommandPalette();recording=false;perform(stop);project=emptyProject();project.songMode=false;project.loop=true;project.bpm=300;project.patterns[0].length=1;project.clips.clear();project.patterns[0].lanes[7]={{0,.15,60,.7f,.6f,2},{.5,.2,64,.8f}};selectedTrack=7;selectedNote=0;selectedNotes={0,1};currentFile=File();publish();undoStack.clear();redoStack.clear();dirty=false;setSize(1440,940);resetLayout();showPane(pianoPane);
