    lane()={{.02,.1,60,.8f},{.12,.1,64,.8f}};publish();draw();hit=std::find_if(hits.begin(),hits.end(),[](const Hit& h){return h.action==rackGrid&&h.data==7&&h.extra==0;});bool foundStep=hit!=hits.end();if(foundStep){auto point=hit->rect.getCentre();auto time=Time::getCurrentTime();MouseEvent event(Desktop::getInstance().getMainMouseSource(),point,ModifierKeys(ModifierKeys::altModifier|ModifierKeys::rightButtonModifier),1,0,0,0,0,this,this,time,point,time,1,false);mouseDown(event);mouseUp(event);}check(foundStep&&selectedNotes==std::set<int>({0,1}),"rack condition selection includes every off-grid/chord note shown in the clicked step");PopupMenu::dismissAllActiveMenus();check(applyNoteCondition(3,3,revision,0,7,conditionSelection())&&lane()[0].conditionStep==3&&lane()[1].conditionStep==3,"one rack condition edit changes all notes represented by a step together");
